# این راهبرد در نسخه‌ی نهایی با pk=81 ادغام شده؛ قبل از حذف تأیید شد که
# به هیچ پروژه‌ای وصل نیست (فقط ۲ آیتم SWOT مبنا داشت که پیوندشان هم حذف می‌شود).
DELETE_TOWS_PK = 82


class Command(BaseCommand):
    help = "به‌روزرسانی SWOT/TOWS «گارانتی خودرو» طبق نسخه‌ی نهایی + حذف ۱ راهبرد ادغام‌شده."

    def handle(self, *args, **options):
        updated_swot, missing_swot = 0, []
        for pk, new_text in SWOT_UPDATES.items():
            try:
                obj = SWOTItem.objects.get(pk=pk)
            except SWOTItem.DoesNotExist:
                missing_swot.append(pk)
                continue
            obj.text = new_text
            obj.save()
            updated_swot += 1

        updated_tows, missing_tows = 0, []
        for pk, new_text in TOWS_UPDATES.items():
            try:
                obj = TOWSStrategy.objects.get(pk=pk)
            except TOWSStrategy.DoesNotExist:
                missing_tows.append(pk)
                continue
            obj.text = new_text
            obj.save()
            updated_tows += 1

        deleted = False
        try:
            obj = TOWSStrategy.objects.get(pk=DELETE_TOWS_PK)
            if obj.initiatives.exists():
                self.stdout.write(self.style.ERROR(
                    f"⚠️ توقف امنیتی: pk={DELETE_TOWS_PK} به {obj.initiatives.count()} پروژه وصله! حذف انجام نشد."
                ))
            else:
                obj.delete()
                deleted = True
        except TOWSStrategy.DoesNotExist:
            pass

        self.stdout.write(self.style.SUCCESS(
            f"{updated_swot} آیتم SWOT و {updated_tows} راهبرد TOWS «گارانتی خودرو» به‌روزرسانی شد."
            + (f" ۱ راهبرد ادغام‌شده (pk={DELETE_TOWS_PK}) حذف شد." if deleted else "")
        ))
        if missing_swot or missing_tows:
            self.stdout.write(self.style.ERROR(
                f"⚠️ شناسه‌های پیدانشده — SWOT: {missing_swot} | TOWS: {missing_tows}"
            ))
